        abstract static class Modulus<M extends Modulus<M>> {
            final java.util.List<Integer> factList = new java.util.ArrayList<>();
            final java.util.List<Integer> invFactList = new java.util.ArrayList<>();

            public abstract long modulus();

            public Modulus() {
                factList.add(1);
                invFactList.add(1);
            }

            public long fact(int n) {
                while (factList.size() <= n) {
                    int last = factList.get(factList.size() - 1);
                    factList.add((int) mult(last, factList.size()));
                }
                return factList.get(n);
            }

