                    invArr[0] = inv(fact(n));
                    for (int i = 1; i < invArr.length; i++) {
                        invArr[i] = mult(invArr[i - 1], n - i + 1);
                    }
                    for (int i = invArr.length - 1; i >= 0; i--) {
                        invFactList.add((int) invArr[i]);
                    }
                }
                return invFactList.get(n);
            }

            public long ncr(int n, int r) {
                if (n < 0 || r < 0 || n < r) return 0;
                return mult(fact(n), mult(fInv(r), fInv(n - r)));
            }

            public long smallInv(int n) {
                return mult(fInv(n), fact(n - 1));
            }

            public long normalize(long x) {
                long m = modulus();
                x %= m;
                if (x < 0) x += m;
                return x;
            }

            public long add(long a, long b) {
