                long m = modulus();
                return res < 0 ? res + m : res;
            }

            public long mult(long a, long b) {
                return (a * b) % modulus();
            }

            public long inv(long value) {
                long g = modulus(), x = 0, y = 1;
                for (long r = value; r != 0; ) {
                    long q = g / r;
                    long temp = g % r;
                    g = r;
                    r = temp;

                    long t = x - q * y;
                    x = y;
                    y = t;
                }
                assert g == 1;
                assert y == modulus() || y == -modulus();
                return normalize(x);
            }
        }
    }
