#include <bits/stdc++.h>
using namespace std;

struct NumberTheory {
    struct Mod998 {
        long long modulus() { return 998244353LL; }

        long long add(long long a, long long b) {
            long long s = a + b;
            long long m = modulus();
            return s >= m ? s - m : s;
        }

        long long subtract(long long a, long long b) {
            long long res = a - b;
            long long m = modulus();
            return res < 0 ? res + m : res;
        }

        long long mult(long long a, long long b) {
            return (a % modulus() * b % modulus()) % modulus();
        }

        long long inv(long long value) {
            long long g = modulus(), x = 0, y = 1;
            for (long long r = value; r != 0; ) {
                long long q = g / r;
                long long temp = g % r;
                g = r;
                r = temp;

                long long t = x - q * y;
                x = y;
                y = t;
            }
            assert(g == 1);
            assert(y == modulus() || y == -modulus());
            return (x % modulus() + modulus()) % modulus();
        }

        long long fact(int n, vector<long long>& factList) {
            while ((int)factList.size() <= n) {
                int last = (int)factList.size() - 1;
                factList.push_back(mult(factList.back(), last + 1));
            }
            return factList[n];
        }

        long long fInv(int n, vector<long long>& invFactList, vector<long long>& factList) {
            int lastIdx = (int)invFactList.size() - 1;
            if (lastIdx < n) {
                vector<long long> invArr(n - lastIdx);
                invArr[0] = inv(fact(n, factList));
                for (int i = 1; i < (int)invArr.size(); i++) {
                    invArr[i] = mult(invArr[i - 1], n - i + 1);
                }
                for (int i = (int)invArr.size() - 1; i >= 0; i--) {
                    invFactList.push_back(invArr[i]);
                }
            }
            return invFactList[n];
        }

        long long ncr(int n, int r, vector<long long>& factList, vector<long long>& invFactList) {
            if (n < 0 || r < 0 || n < r) return 0;
            return mult(fact(n, factList), mult(fInv(r, invFactList, factList), fInv(n - r, invFactList, factList)));
        }

        long long smallInv(int n, vector<long long>& factList, vector<long long>& invFactList) {
            return mult(fInv(n, invFactList, factList), fact(n - 1, factList));
        }
    };
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;

    NumberTheory::Mod998 mod;

    vector<long long> factList = {1};
    vector<long long> invFactList = {1};

    long long modVal = mod.modulus();

    // Compute modular inverse of n + m
    long long invNPlusM = mod.fInv(n + m, invFactList, factList);

    long long phaseSize = 1;
    long long p = 1;
    for (int i = 0; p != 0; i++) {
        long long numerator = mod.mult(p, n - i);
        long long denominator = mod.smallInv(n + m - i, factList, invFactList);
        p = mod.mult(numerator, denominator);
        phaseSize = mod.add(phaseSize, p);
    }

    long long answer = 0;
    for (int k = 1; k <= n; k++) {
        long long numPhases = mod.mult(m + k, mod.smallInv(k, factList, invFactList));
        long long term = mod.mult(mod.ncr(n, k, factList, invFactList), mod.mult(numPhases, phaseSize));
        if ((k & 1) == 1)
            answer = mod.add(answer, term);
        else
            answer = mod.subtract(answer, term);
    }

    cout << answer << "\n";

    return 0;
}
